import { createRoot } from "react-dom/client";
import { VehicleForm } from "../../src/modules/transport/forms";
declare global{interface Window{__vehicleRegistrationSubmissions:Record<string,string>[];__vehicleRegistrationReject:boolean;__vehicleRegistrationSave:(form:FormData)=>Promise<{error:string;success:string;id?:string}>}}
window.__vehicleRegistrationSubmissions=[];window.__vehicleRegistrationReject=false;
window.__vehicleRegistrationSave=async form=>{const data=Object.fromEntries([...form].map(([key,value])=>[key,String(value)]));data.files=JSON.stringify(form.getAll("documents").filter((f):f is File=>f instanceof File&&f.size>0).map(f=>f.name));window.__vehicleRegistrationSubmissions.push(data);return window.__vehicleRegistrationReject?{error:"Rechazo sintético. Conservamos los datos y archivos.",success:""}:{error:"",success:"Conductor, vehículo y documentos guardados.",id:data.id||crypto.randomUUID()};};
const id=(n:number)=>`10000000-0000-4000-8000-${String(n).padStart(12,"0")}`;
const edit=location.search.includes("edit"),vehicle={id:id(1),plate:"TEST-01",description:"Unidad sintética",responsibleId:id(2),active:true,version:1,districtIds:[id(3)],centerIds:[id(4)]};
createRoot(document.getElementById("root")!).render(<main className="mx-auto max-w-3xl space-y-6 p-5"><h1 className="text-2xl font-semibold">{edit?"Editar conductor y vehículo":"Registrar conductor y vehículo"}</h1><section className="rounded-xl border bg-card p-5"><VehicleForm registrationId={id(5)} vehicle={edit?vehicle:undefined} people={[{id:id(2),fullName:"Conductor de prueba",phone:"",email:"",version:"2020-01-01"}]} districts={[{id:id(3),name:"Distrito de prueba"}]} centers={[{id:id(4),name:"Escuela de prueba",districtId:id(3)}]} initialCenterId={id(4)}/></section></main>);
